question:
给定如下算法，其时间复杂度为（）。

bool f(int arr[], int n, int target) {
    for (int i = 0; i < (1 << n); i++) {
        int sum = 0;
        for (int j = 0; j < n; j++)
            if (i & (1 << j)) {
                sum += arr[j];
            }
    }
    if (sum == target) return true;
    return false;
}

